const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var newDelhi = ee.Geometry.Point([77.2090, 28.6139]).buffer(10000); // 10km buffer
  var modinagar = ee.Geometry.Point([77.5500, 28.5700]).buffer(10000);
  var greaterNoida = ee.Geometry.Point([77.5037, 28.4742]).buffer(10000);

  var date = '2014-01-30';
  var startDate = ee.Date(date);
  var endDate = startDate.advance(1, 'day');

  // 2. Data Acquisition - MODIS Terra Cloud Mask
  var collection = ee.ImageCollection('MODIS/006/MOD35_L2')
                    .filterDate(startDate, endDate)
                    .filterBounds(newDelhi);

  var collectionSize = collection.size().getInfo();
  console.log('MOD35_L2 collection size:', collectionSize);

  // If no data, try MODIS Aqua
  if (collectionSize === 0) {
    console.log('Trying MODIS Aqua (MYD35_L2)...');
    collection = ee.ImageCollection('MODIS/006/MYD35_L2')
                  .filterDate(startDate, endDate)
                  .filterBounds(newDelhi);
    collectionSize = collection.size().getInfo();
    console.log('MYD35_L2 collection size:', collectionSize);
  }

  // If still no data, output C1
  if (collectionSize === 0) {
    console.log('No cloud mask data found for', date);
    console.log('<answer>C1</answer>');
    return;
  }

  // Get the first image (should be only one for the day)
  var image = collection.first();

  // 3. Processing: Extract cloud confidence from Cloud_Mask band (bits 0-1)
  var cloudMask = image.select('Cloud_Mask');
  var cloudConfidence = cloudMask.bitwiseAnd(3); // 3 = binary 11, extracts last 2 bits
  // Values: 0=confident clear, 1=probably clear, 2=probably cloudy, 3=confident cloudy
  // We consider 2 and 3 as cloudy/fog
  var fogMask = cloudConfidence.gte(2); // 1 for fog/cloud, 0 for clear

  // Function to compute fog percentage for a geometry
  function computeFogPercentage(geometry) {
    // Count total pixels
    var totalCount = fogMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    }).get('Cloud_Mask').getInfo();

    if (totalCount === 0) {
      return {percentage: null, count: 0};
    }

    // Count fog pixels (value = 1)
    var fogCount = fogMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    }).get('Cloud_Mask').getInfo();

    var percentage = (fogCount / totalCount) * 100;
    return {percentage: percentage, count: totalCount};
  }

  // Compute for each region
  var delhiResult = computeFogPercentage(newDelhi);
  var modinagarResult = computeFogPercentage(modinagar);
  var greaterNoidaResult = computeFogPercentage(greaterNoida);

  console.log('New Delhi - Fog %:', delhiResult.percentage !== null ? delhiResult.percentage.toFixed(2) : 'No valid pixels', 'Total pixels:', delhiResult.count);
  console.log('Modinagar - Fog %:', modinagarResult.percentage !== null ? modinagarResult.percentage.toFixed(2) : 'No valid pixels', 'Total pixels:', modinagarResult.count);
  console.log('Greater Noida - Fog %:', greaterNoidaResult.percentage !== null ? greaterNoidaResult.percentage.toFixed(2) : 'No valid pixels', 'Total pixels:', greaterNoidaResult.count);

  // 4. Validation & Final Answer
  // Check for no valid pixels (C2)
  if (delhiResult.count === 0 || modinagarResult.count === 0 || greaterNoidaResult.count === 0) {
    console.log('One or more regions have 0 valid pixels.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for calculation failure (C3)
  if (delhiResult.percentage === null || modinagarResult.percentage === null || greaterNoidaResult.percentage === null ||
      isNaN(delhiResult.percentage) || isNaN(modinagarResult.percentage) || isNaN(greaterNoidaResult.percentage)) {
    console.log('Invalid percentage calculation.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare percentages
  var delhiLessThanModinagar = delhiResult.percentage < modinagarResult.percentage;
  var delhiLessThanGreaterNoida = delhiResult.percentage < greaterNoidaResult.percentage;

  if (delhiLessThanModinagar && delhiLessThanGreaterNoida) {
    console.log('New Delhi has less fog coverage than both surrounding areas.');
    console.log('<answer>A</answer>');
  } else {
    console.log('New Delhi does not have less fog coverage than both surrounding areas.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
